return ['domain'=>'block-inserter-filter','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'Block Inserter Filter 2.1.1','pot-creation-date'=>'2026-09-14 12:57+0000','po-revision-date'=>'2026-09-14 12:57+0000','x-generator'=>'WP-CLI 2.x','messages'=>['Block Inserter Filter'=>'Block Inserter Filter','Hides individual Gutenberg blocks and embed variations from the block inserter, site-wide. Configurable per block by administrators, with optional GenerateBlocks integration.'=>'Ukrywa pojedyncze bloki Gutenberga i warianty osadzania z narzędzia wstawiania bloków w całej witrynie. Konfigurowane przez administratorów dla każdego bloku, z opcjonalną integracją z GenerateBlocks.','Jörn Gorres'=>'Jörn Gorres','https://joern.gorres.com'=>'https://joern.gorres.com','Hide Blocks'=>'Ukryj bloki','You do not have permission to do this.'=>'Nie masz uprawnień do wykonania tej czynności.','Settings saved.'=>'Ustawienia zapisane.','Registered blocks: %1$d. Currently hidden: %2$d blocks and %3$d embed variations.'=>'Zarejestrowane bloki: %1$d. Obecnie ukryte: %2$d bloków i %3$d wariantów osadzania.','Checked blocks are removed from the block inserter for all users. Existing content using hidden blocks remains visible – only inserting new instances is blocked.'=>'Zaznaczone bloki są usuwane z narzędzia wstawiania bloków dla wszystkich użytkowników. Istniejąca treść z ukrytymi blokami pozostaje widoczna – blokowane jest tylko wstawianie nowych wystąpień.','Certain core blocks (Paragraph, Heading, List, Image, Group, Columns) always stay available as a safety net and cannot be hidden here.'=>'Niektóre bloki podstawowe (Akapit, Nagłówek, Lista, Obrazek, Grupa, Kolumny) są zawsze dostępne jako zabezpieczenie i nie można ich tutaj ukryć.','Search blocks'=>'Szukaj bloków','Search blocks…'=>'Szukaj bloków…','Choose grouping'=>'Wybierz grupowanie','By category'=>'Według kategorii','By namespace'=>